const payload = $input.item.json.body || $input.item.json;
const record = payload.record || payload;

let sourceModule = 'desconocido';
if (record.orden_taller_id) sourceModule = 'taller';
else if (record.orden_motor_id) sourceModule = 'motores';
else if (record.proyecto_id) sourceModule = 'automatizacion';
else if (record.cotizacion_id) sourceModule = 'ventas';

const targetModules = [];
if (sourceModule === 'taller' || sourceModule === 'motores' || sourceModule === 'automatizacion') {
  targetModules.push('ventas');
}
if (record.evento && record.evento.includes('compra')) {
  targetModules.push('compras');
}

return [{ json: { sourceModule, targetModules, evento: record.evento || '', descripcion: record.descripcion || '', metadata: record.metadata || {}, record } }];

