const text = $input.item.json.text || $input.item.json.content || '{}';
let parsed;
try { parsed = typeof text === 'string' ? JSON.parse(text) : text; } catch { parsed = { notifications: [] }; }
const notifications = parsed.notifications || [];
const results = [];
for (const n of notifications) {
  results.push({ json: n });
}
if (results.length === 0) results.push({ json: { para: 'admin', tipo: 'cross_module', mensaje: 'Evento sin módulo objetivo: ' + ($node['Determine Module'].json.evento || 'desconocido') } });
return results;
